import pty, os, sys, time, select, re

bin_path = sys.argv[1]
keys = sys.argv[2:]

pid, fd = pty.fork()
if pid == 0:
    os.execvp(bin_path, [bin_path])
else:
    os.write(fd, b"")
    time.sleep(1.5)
    try:
        os.write(fd, b"\x1b]0;\x07")  # noop
    except OSError:
        pass
    buf = b""
    def drain(timeout=0.5):
        global buf
        while True:
            r, _, _ = select.select([fd], [], [], timeout)
            if not r:
                break
            try:
                chunk = os.read(fd, 65536)
            except OSError:
                break
            if not chunk:
                break
            buf += chunk

    drain(2.0)
    for k in keys:
        if k == "SLEEP":
            time.sleep(1)
            continue
        os.write(fd, k.encode().decode('unicode_escape').encode('latin1'))
        drain(1.0)

    drain(1.0)
    try:
        os.kill(pid, 15)
    except ProcessLookupError:
        pass

    # strip ANSI escape sequences for readability
    text = buf.decode('utf-8', errors='replace')
    ansi_escape = re.compile(r'(\x1b\[[0-9;?]*[a-zA-Z])|(\x1b\][^\x07]*\x07)|(\x1b[()][A-Z0-9])')
    clean = ansi_escape.sub('', text)
    sys.stderr.write(clean)

